#[test]
fn main_window_title_hides_internal_synthetic_paths() {
    let internal = PathBuf::from(r"C:\data\__reading_history__");
    assert_eq!(
        main_window_title(Some(&internal), true, false, None, false),
        "読書履歴 - mimageviewer"
    );
    assert_eq!(
        main_window_title(Some(&internal), false, true, None, false),
        "サブフォルダ展開 - mimageviewer"
    );
    assert_eq!(
        main_window_title(Some(&internal), false, false, Some("未整理"), false),
        "スマートフォルダ: 未整理 - mimageviewer"
    );
}

#[test]
fn main_window_title_preserves_real_path_and_indexing_suffix() {
    let folder = PathBuf::from(r"C:\Pictures");
    assert_eq!(
        main_window_title(Some(&folder), false, false, None, true),
        r"C:\Pictures - mimageviewer  (インデックス更新中)"
    );
    assert_eq!(
        main_window_title(None, false, false, None, false),
        "mimageviewer"
    );
}

/// `App::new_for_test` に渡すテスト設定。
///
/// Phase C では実プロセスの `data_dir::init` を経由せず、`set_test_override` で
/// `TempDir` を差し込む。App 内の全 DB/インデクサ open はその data_dir を参照する。
struct AppTestConfig {
    /// テスト用データディレクトリ。`data_dir::set_test_override(Some(...))` に設定済みの
    /// パスを渡す。(呼び出し側の `TempDir` が App より長生きする必要あり)
    data_dir: std::path::PathBuf,
    /// 起動時に `settings.json` をこの内容で上書きしてから App::default を呼ぶ。
    /// None なら `Settings::load` が空ファイルから default 設定を作る。
    settings: Option<crate::settings::Settings>,
}

impl App {
    /// テスト用コンストラクタ。本番の `App::default` と同じ DB/indexer open 経路を
    /// 通すが、以下が異なる:
    ///
    /// 1. `config.data_dir` を `data_dir::set_test_override` 経由で強制する前提 (呼び出し側で)
    /// 2. `config.settings` があれば `settings.json` に書き出してから load する
    /// 3. 名前索引 supervisor の初期 spawn は行わない
    ///    (呼び出し側が `spawn_initial_name_index_supervisors()` を明示的に呼ぶ)
    /// 4. 初期サイズ / font / theme は設定しない (テスト側で Context を用意する想定)
    ///
    /// 注意: Tantivy / SQLite / notify-rs などの実スレッドは通常どおり起動するので、
    /// テスト終了時には `drop(app)` で正しく停止すること (IndexerManager::drop が
    /// supervisor を signal_stop→join で止める)。
    fn new_for_test(config: AppTestConfig) -> Self {
        // settings.json をあらかじめ書いておく (App::default 内の Settings::load が拾う)
        if let Some(settings) = &config.settings {
            std::fs::create_dir_all(&config.data_dir).ok();
            let json = serde_json::to_string_pretty(settings).expect("serialize settings");
            std::fs::write(config.data_dir.join("settings.json"), json)
                .expect("write settings.json");
        }
        // data_dir::get() はこの時点で config.data_dir を返さなければならない
        debug_assert_eq!(
            crate::data_dir::get(),
            config.data_dir,
            "data_dir::set_test_override(Some(config.data_dir)) を先に呼ぶこと"
        );
        let mut app = App::default();
        // 起動時 purge-retry worker はテストハーネスでは既定オフにする。本番の既定は true
        // (app.rs:9667) だが、テストで有効だと `App::update` を回す並列テストがこの worker を
        // spawn し、プロセスグローバルの data_dir override 経由で別テストの rating.db 等を
        // 触ってフレークする (undo_restores_zip_book_container_rating_key ほか、並列時のみ稀に
        // 失敗)。purge-retry の journal 再試行そのものを検証するテストだけ明示的に true へ
        // 戻して driver を回す契約にする (review-v2.3.0 追補19: テスト隔離)。
        app.delete_purge_retry_needed = false;
        // `spawn_initial_name_index_supervisors` はテスト側で必要なときだけ呼ぶ契約
        app
    }
}

fn scan_media_names(dir: &std::path::Path) -> Vec<String> {
    let mut names: Vec<String> = scan_directory(dir)
        .all_media
        .into_iter()
        .filter_map(|(path, _, _, _)| {
            path.file_name()
                .and_then(|name| name.to_str())
                .map(str::to_owned)
        })
        .collect();
    names.sort();
    names
}

fn scan_folder_names(dir: &std::path::Path) -> Vec<String> {
    let mut names: Vec<String> = scan_directory(dir)
        .folders
        .into_iter()
        .filter_map(|(item, _)| {
            if let GridItem::Folder(path) = item {
                path.file_name()
                    .and_then(|name| name.to_str())
                    .map(str::to_owned)
            } else {
                None
            }
        })
        .collect();
    names.sort();
    names
}

fn scan_convertible_archive_names(dir: &std::path::Path) -> Vec<String> {
    let mut names: Vec<String> = scan_directory(dir)
        .folders
        .into_iter()
        .filter_map(|(item, _)| match item {
            GridItem::ConvertibleArchive { path, .. } => path
                .file_name()
                .and_then(|name| name.to_str())
                .map(str::to_owned),
            _ => None,
        })
        .collect();
    names.sort();
    names
}

#[test]
fn comic_export_composition_applies_multiply_marker() {
    let base = egui::ColorImage::new([8, 8], vec![egui::Color32::WHITE; 64]);
    let mut bubble = comic_core::BubbleObject::default();
    bubble.shape = comic_core::BubbleShape::RoundRect {
        half_w: 2.0,
        half_h: 2.0,
        corner_px: 0.0,
    };
    bubble.fill = Some(comic_core::Rgba::new(255, 235, 59, 255));
    bubble.fill_opacity = 1.0;
    bubble.blend = comic_core::FillBlend::Multiply;
    bubble.outline.width_px = 0.0;
    bubble.text = comic_core::TextBlock::default();
    bubble.auto_size = false;
    let object = comic_core::AnnotationObject::new_bubble(1, (4.0, 4.0), bubble);

    let result = composite_comic_objects_for_export(
        &base,
        &[object],
        &comic_core::FontSet::new(),
        &comic_core::StampImages::new(),
    );

    assert_eq!(
        result.pixels[4 * 8 + 4].to_srgba_unmultiplied(),
        [255, 235, 59, 255]
    );
}

#[test]
fn fullscreen_pdf_loads_are_not_pruned_by_grid_epoch() {
    for priority in [
        crate::pdf_loader::JobPriority::Critical,
        crate::pdf_loader::JobPriority::HighNormal,
        crate::pdf_loader::JobPriority::Normal,
    ] {
        assert_eq!(
            App::fs_pdf_render_context_epoch(priority),
            0,
            "fullscreen fs_load PDF renders must be owned by fs_pending, not the main-grid epoch"
        );
    }
}

#[test]
fn fullscreen_pdf_interrupted_render_is_cancel_like() {
    let interrupted =
        std::io::Error::new(std::io::ErrorKind::Interrupted, "context epoch advanced");
    assert!(
        App::fs_pdf_render_error_is_cancel_like(false, &interrupted),
        "PDF render Interrupted must not publish FsLoadResult::Failed"
    );

    let real_error = std::io::Error::new(std::io::ErrorKind::Other, "pdfium failed");
    assert!(
        !App::fs_pdf_render_error_is_cancel_like(false, &real_error),
        "real PDF render errors should still publish failure"
    );
    assert!(
        App::fs_pdf_render_error_is_cancel_like(true, &real_error),
        "explicit fs_pending cancel remains cancel-like regardless of error kind"
    );
}

#[test]
fn scan_directory_can_ignore_convertible_archives() {
    let tmp = TempDir::new().expect("tempdir");
    std::fs::write(tmp.path().join("book.rar"), b"rar").unwrap();
    std::fs::write(tmp.path().join("book.7z"), b"7z").unwrap();
    std::fs::write(tmp.path().join("book.lzh"), b"lzh").unwrap();
    std::fs::write(tmp.path().join("book.zip"), b"zip").unwrap();

    let scan = scan_directory_with_convertible_archives(tmp.path(), false, false);

    assert!(scan.folders.iter().any(|(item, _)| matches!(item, GridItem::ZipFile(path) if path.file_name().and_then(|n| n.to_str()) == Some("book.zip"))));
    assert!(
        !scan
            .folders
            .iter()
            .any(|(item, _)| matches!(item, GridItem::ConvertibleArchive { .. })),
        "convertible archives should be hidden from the folder list"
    );
}

#[test]
fn rar_folder_scan_keeps_all_volumes_visible_without_header_io() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/archives/rar-multipart-filename-regression");
    let standalone_names = [
        "○×△□ Vol.1.rar",
        "○×△□ Vol.2.rar",
        "○×△□ Vol.2a.rar",
        "○×△□ Vol.10.rar",
        "○×△□ Vol.10a.rar",
        "○×△□ Vol.123.rar",
        "○×△□ Vol.１.rar",
    ];
    for name in standalone_names {
        crate::rar_loader::inspect_for_direct_read(&root.join(name)).unwrap();
    }
    let mut expected: Vec<String> = standalone_names.into_iter().map(str::to_owned).collect();
    expected.sort();
    assert_eq!(scan_convertible_archive_names(&root), expected);

    let split_root = root.join("real-split-control");
    let first = split_root.join("real-split-control.part1.rar");
    let second = split_root.join("real-split-control.part2.rar");
    crate::rar_loader::inspect_for_direct_read(&first).unwrap();
    crate::rar_loader::inspect_for_direct_read(&second).unwrap();
    assert_eq!(
        scan_convertible_archive_names(&split_root),
        vec![
            "real-split-control.part1.rar".to_string(),
            "real-split-control.part2.rar".to_string(),
        ]
    );
}

#[cfg(windows)]
#[test]
fn scan_directory_lists_windows_directory_symlink_and_file_symlink() {
    let tmp = TempDir::new().expect("tempdir");
    let target_dir = tmp.path().join("target-dir");
    let link_dir = tmp.path().join("link-dir");
    std::fs::create_dir(&target_dir).unwrap();
    if std::os::windows::fs::symlink_dir(&target_dir, &link_dir).is_err() {
        return;
    }
    assert_eq!(
        scan_folder_names(tmp.path()),
        vec!["link-dir", "target-dir"]
    );

    let target_image = tmp.path().join("target.jpg");
    let link_image = tmp.path().join("link-image.jpg");
    std::fs::write(&target_image, b"image").unwrap();
    if std::os::windows::fs::symlink_file(&target_image, &link_image).is_err() {
        return;
    }

    assert_eq!(
        scan_media_names(tmp.path()),
        vec!["link-image.jpg", "target.jpg"]
    );
}

