#[test]
fn startup_archive_open_auto_fullscreen_follows_setting_and_file_kind() {
    let tmp = TempDir::new().expect("tempdir");
    let zip = tmp.path().join("book.zip");
    let cbz = tmp.path().join("book.cbz");
    let pdf = tmp.path().join("scan.pdf");
    let rar = tmp.path().join("book.rar");
    let seven_z = tmp.path().join("book.7z");
    let image = tmp.path().join("cover.jpg");
    let folder = tmp.path().join("folder");
    for path in [&zip, &cbz, &pdf, &rar, &seven_z, &image] {
        std::fs::write(path, b"dummy").unwrap();
    }
    std::fs::create_dir(&folder).unwrap();

    let mut settings = crate::settings::Settings::default();
    settings.auto_fullscreen_zip_pdf = false;
    assert!(!startup_openable_should_auto_fullscreen(
        &settings,
        &zip,
        crate::folder_tree::OpenablePathKind::File,
    ));

    settings.auto_fullscreen_zip_pdf = true;
    for path in [&zip, &cbz, &pdf, &rar, &seven_z] {
        assert!(
            startup_openable_should_auto_fullscreen(
                &settings,
                path,
                crate::folder_tree::OpenablePathKind::File,
            ),
            "{} should inherit the explicit archive open fullscreen setting",
            path.display()
        );
    }
    assert!(!startup_openable_should_auto_fullscreen(
        &settings,
        &image,
        crate::folder_tree::OpenablePathKind::File,
    ));
    assert!(!startup_openable_should_auto_fullscreen(
        &settings,
        &folder,
        crate::folder_tree::OpenablePathKind::Directory,
    ));

    settings.auto_fullscreen_image_folders = true;
    assert!(
        startup_openable_should_auto_fullscreen(
            &settings,
            &folder,
            crate::folder_tree::OpenablePathKind::Directory,
        ),
        "image-only folder fullscreen is decided after directory load, but explicit folder opens should carry the intent"
    );

    settings.auto_fullscreen_zip_pdf = false;
    assert!(
        !startup_openable_should_auto_fullscreen(
            &settings,
            &folder,
            crate::folder_tree::OpenablePathKind::Directory,
        ),
        "folder option is subordinate to the main direct-page setting"
    );

    settings.detached_viewer_open_images_in_window = true;
    assert!(
        startup_openable_should_auto_fullscreen(
            &settings,
            &zip,
            crate::folder_tree::OpenablePathKind::File,
        ),
        "multi-window viewer mode forces ZIP/PDF direct open without mutating the saved full-feature preference"
    );
    assert!(
        startup_openable_should_auto_fullscreen(
            &settings,
            &folder,
            crate::folder_tree::OpenablePathKind::Directory,
        ),
        "multi-window viewer mode also enables the image-only folder option when that checkbox is on"
    );
}

#[test]
fn auto_fullscreen_image_only_folder_opens_page_after_load() {
    let mut app = phase_c_support::setup_app();
    let folder = app.tmp.path().join("pages");
    std::fs::create_dir(&folder).unwrap();
    std::fs::write(folder.join("001.jpg"), b"dummy").unwrap();
    std::fs::write(folder.join("002.png"), b"dummy").unwrap();

    app.settings.auto_fullscreen_zip_pdf = true;
    app.settings.auto_fullscreen_image_folders = true;
    app.pending_auto_fs_open = true;

    app.load_folder(folder.clone());

    assert_eq!(app.current_folder.as_deref(), Some(folder.as_path()));
    assert_eq!(app.fullscreen_idx, Some(0));
    assert_eq!(app.selected, Some(0));
    assert!(
        !app.pending_auto_fs_open,
        "folder auto-open request is one-shot"
    );
}

#[cfg(windows)]
#[test]
fn auto_fullscreen_image_only_folder_preserves_grid_intent_for_always_new_detached() {
    let mut app = phase_c_support::setup_app();
    let folder = app.tmp.path().join("detached_pages");
    std::fs::create_dir(&folder).unwrap();
    std::fs::write(folder.join("001.jpg"), b"dummy").unwrap();
    std::fs::write(folder.join("002.png"), b"dummy").unwrap();

    app.settings.auto_fullscreen_zip_pdf = true;
    app.settings.auto_fullscreen_image_folders = true;
    app.settings.detached_viewer_open_images_in_window = true;
    app.pending_auto_fs_open = true;

    app.load_folder(folder.clone());

    assert_eq!(app.current_folder.as_deref(), Some(folder.as_path()));
    assert_eq!(app.fullscreen_idx, Some(0));
    assert_eq!(app.viewer_presentation, ViewerPresentation::DetachedWindow);
    assert!(
        app.detached_viewer_focus_requested,
        "image-only folder auto fullscreen happens after enumeration, but it is still an explicit grid/open request and must focus the new detached window"
    );
    assert!(
        app.detached_viewer_window_id.is_some(),
        "always-new detached image folders should allocate a detached viewport instead of treating the open as continuation navigation"
    );
    assert!(
        !app.fs_open_intent_from_grid,
        "open_fullscreen consumes the restored grid intent"
    );
}

#[test]
fn auto_fullscreen_image_folder_ignores_mixed_folder_after_load() {
    let mut app = phase_c_support::setup_app();
    let folder = app.tmp.path().join("mixed");
    std::fs::create_dir(&folder).unwrap();
    std::fs::create_dir(folder.join("child")).unwrap();
    std::fs::write(folder.join("001.jpg"), b"dummy").unwrap();

    app.settings.auto_fullscreen_zip_pdf = true;
    app.settings.auto_fullscreen_image_folders = true;
    app.pending_auto_fs_open = true;

    app.load_folder(folder.clone());

    assert_eq!(app.current_folder.as_deref(), Some(folder.as_path()));
    assert_eq!(app.fullscreen_idx, None);
    assert!(
        !app.pending_auto_fs_open,
        "non-matching folder still consumes stale request"
    );
}

// ── cell_has_lower_left_container_badge ───────────────────────────────────
//
// レーティング ★ バッジを左下に出す際、コンテナバッジ (folder 名 / "ZIP" / "PDF" /
// "7z" / "LZH") と重ねないために使う純関数。ユーザー報告「フォルダ名と ★ が重なる」
// 退行ガード。

#[test]
fn lower_left_container_badge_yes_for_folder_when_loaded() {
    use crate::grid_item::GridItem;
    let dummy_tex = {
        let ctx = egui::Context::default();
        ctx.load_texture(
            "dummy",
            egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE]),
            Default::default(),
        )
    };
    let folder = GridItem::Folder(PathBuf::from("c:/x"));
    let loaded = ThumbnailState::Loaded {
        tex: dummy_tex,
        from_cache: false,
        from_edit_preview: false,
        rendered_at_px: 128,
        source_dims: None,
    };
    assert!(cell_has_lower_left_container_badge(&folder, &loaded));
}

#[test]
fn lower_left_container_badge_no_for_folder_when_pending() {
    use crate::grid_item::GridItem;
    let folder = GridItem::Folder(PathBuf::from("c:/x"));
    assert!(!cell_has_lower_left_container_badge(
        &folder,
        &ThumbnailState::Pending
    ));
    assert!(!cell_has_lower_left_container_badge(
        &folder,
        &ThumbnailState::Evicted
    ));
    assert!(!cell_has_lower_left_container_badge(
        &folder,
        &ThumbnailState::Failed
    ));
}

#[test]
fn lower_left_container_badge_always_yes_for_archive_types() {
    use crate::grid_item::GridItem;
    let zip = GridItem::ZipFile(PathBuf::from("c:/x.zip"));
    let pdf = GridItem::PdfFile(PathBuf::from("c:/x.pdf"));
    let arch = GridItem::ConvertibleArchive {
        path: PathBuf::from("c:/x.7z"),
        format: crate::archive_converter::ArchiveFormat::SevenZ,
    };
    // どの thumb 状態でも常に true (= 描画パスは Loaded/Pending/Evicted/Failed すべて
    // 最後に badge_fn を呼ぶ)
    for thumb in [
        ThumbnailState::Pending,
        ThumbnailState::Evicted,
        ThumbnailState::Failed,
    ] {
        assert!(cell_has_lower_left_container_badge(&zip, &thumb));
        assert!(cell_has_lower_left_container_badge(&pdf, &thumb));
        assert!(cell_has_lower_left_container_badge(&arch, &thumb));
    }
}

