        let idx_b = push_image(&mut app, "C:/pics/b.jpg");
        // ratable_page_targets は visible_indices で絞るのでテストで埋めておく
        app.visible_indices = vec![idx_a, idx_b];
        // 2 枚チェック (= 一括対象)
        app.checked.insert(idx_a);
        app.checked.insert(idx_b);
