    fn wait_for_book_op(app: &mut App, ctx: &egui::Context) {
        for _ in 0..100 {
            app.poll_book_op_pending(ctx);
            if app.book_op_pending.is_none() {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        panic!("book operation did not finish");
    }

