    /// 見開き表示中の Ctrl+E は左右ページを 1 つの export snapshot として開く。
    #[test]
    fn open_export_dialog_uses_spread_pixels_when_spread_is_visible() {
        use crate::grid_item::GridItem;
        use crate::settings::SpreadMode;
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/p/a.jpg")));
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/p/b.jpg")));
        app.visible_indices = vec![0, 1];
        app.thumbnails.push(ThumbnailState::Pending);
        app.thumbnails.push(ThumbnailState::Pending);
        let left_pixels =
            egui::ColorImage::new([1, 2], vec![egui::Color32::RED, egui::Color32::RED]);
        let right_pixels =
            egui::ColorImage::new([1, 2], vec![egui::Color32::BLUE, egui::Color32::BLUE]);
        app.fs_cache.insert(
            0,
            FsCacheEntry::Static {
                tex: ctx.load_texture(
                    "export_spread_left",
                    left_pixels.clone(),
                    egui::TextureOptions::LINEAR,
                ),
                pixels: std::sync::Arc::new(left_pixels),
                source_dims: None,
                load_seq: 0,
            },
        );
        app.fs_cache.insert(
            1,
            FsCacheEntry::Static {
                tex: ctx.load_texture(
                    "export_spread_right",
                    right_pixels.clone(),
                    egui::TextureOptions::LINEAR,
                ),
                pixels: std::sync::Arc::new(right_pixels),
                source_dims: None,
                load_seq: 0,
            },
        );
        app.fullscreen_idx = Some(0);
        app.spread_mode = SpreadMode::Ltr;

        app.open_export_dialog_for_current(&ctx, 0);

        let state = app.export_dialog.take().expect("export dialog should open");
        assert!(matches!(
            state.source,
            crate::export_dialog::ExportSource::RenderedSpread
        ));
        assert_eq!(
            state.original_format,
            crate::save_with_metadata::SrcFormat::Other("spread".to_string())
        );
        match state.pixels {
            crate::export_dialog::ExportPixels::Spread { left, right } => {
                assert_eq!(left.base_pixels.size, [1, 2]);
                assert_eq!(right.base_pixels.size, [1, 2]);
                assert_eq!(left.base_pixels.pixels[0], egui::Color32::RED);
                assert_eq!(right.base_pixels.pixels[0], egui::Color32::BLUE);
            }
            crate::export_dialog::ExportPixels::Single(_) => {
                panic!("spread export should snapshot both pages")
            }
        }

        app.open_export_dialog_for_current(&ctx, 1);

        let state = app
            .export_dialog
            .take()
            .expect("export dialog should also open from right page");
        assert!(matches!(
            state.source,
            crate::export_dialog::ExportSource::RenderedSpread
        ));
        match state.pixels {
            crate::export_dialog::ExportPixels::Spread { left, right } => {
                assert_eq!(left.base_pixels.pixels[0], egui::Color32::RED);
                assert_eq!(right.base_pixels.pixels[0], egui::Color32::BLUE);
            }
            crate::export_dialog::ExportPixels::Single(_) => {
                panic!("right-page entry should still snapshot the visible spread")
            }
        }
    }

    /// GitHub issue #1 (app 配線): native は AI 範囲内なのに 4096px レンダで現行が native
    /// より大きい PDF ラスターページを、非 AI / アップスケール ON / ページ個別で AI OFF /
    /// ズーム / デノイズのみ / 高負荷上限 (P2) / 収束の各状態で正しく判定する。AI 有効性を
    /// **ページ個別 effective_params** で見ること (= 見開き相方の個別設定にも追従する、
    /// Codex P1) と、純関数テストが見ない App フィールド抽出の回帰ガード。
    #[test]
    fn pdf_native_rerender_decision_tracks_app_state() {
        use crate::ai::ModelKind;
        use crate::ai::upscale::AiProcessSizeLimit;
        use crate::grid_item::GridItem;
        use crate::settings::AiFeatureMode;
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.settings.ai_feature_mode = AiFeatureMode::HighQuality;
        app.settings.ai_upscale_size_limit = Some(AiProcessSizeLimit::square(2048));
        app.settings.ai_denoise_size_limit = Some(AiProcessSizeLimit::square(2048));
        app.settings.global_preset.upscale_model = None;
        app.settings.global_preset.denoise_model = None;

        // native 100x200 (両軸 2048 未満 = range 内) の PDF ラスターページ。
        app.items.push(GridItem::PdfPage {
            pdf_path: std::path::PathBuf::from("c:/p/doc.pdf"),
            page_num: 0,
            content_type: Some(crate::pdf_loader::PdfPageContentType::Raster { w: 100, h: 200 }),
        });
        let idx = app.items.len() - 1;
        app.fullscreen_idx = Some(idx);
        app.fs_zoom = 1.0;

        // FsCacheEntry の tex は判定に使われない (pixels.size を読む) ので、テスト
        // Context のテクスチャ上限 (2048) を超える pixels でも 1x1 ダミーテクスチャで足りる。
        let dummy_tex = ctx.load_texture(
            "pdf_ai_dummy",
            egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE]),
            egui::TextureOptions::LINEAR,
        );
        let set_cur = |app: &mut App, w: usize, h: usize, tex: &egui::TextureHandle| {
            let px = egui::ColorImage::new([w, h], vec![egui::Color32::WHITE; w * h]);
            app.fs_cache.insert(
                idx,
                FsCacheEntry::Static {
                    tex: tex.clone(),
                    pixels: std::sync::Arc::new(px),
                    source_dims: None,
                    load_seq: 0,
                },
            );
        };

        // 4096px 固定レンダ相当の現行ラスター (long 4000 ≥ 2048 → range 外)。
        set_cur(&mut app, 100, 4000, &dummy_tex);

        // 非 AI (global_preset に AI なし): 再レンダしない。
        assert!(!app.should_native_rerender_pdf_for_ai(idx));

        // 「開いてサイズ確認後にアップスケール ON」= issue 本文のシナリオ。
        // global_preset でアップスケール ON → effective_params 経由で再レンダ要。
        app.settings.global_preset.upscale_model = Some("auto".to_string());
        assert!(app.should_native_rerender_pdf_for_ai(idx));
        // 表示経路の AI 保留判定 (display_should_defer = respect_zoom, no in-flight gate) も
        // 同じく true (4096px に final AI を流さない)。
        assert!(app.display_should_defer_final_ai(idx));

        // Codex P1: ページ個別設定で AI OFF にすると、global が ON でも再レンダしない
        // (= 見開き相方ページが個別に AI OFF のとき final AI も走らないのと一致)。
        app.adjustment_page_params
            .insert(idx, crate::adjustment::AdjustParams::default());
        assert!(!app.should_native_rerender_pdf_for_ai(idx));
        app.adjustment_page_params.remove(&idx);
        assert!(app.should_native_rerender_pdf_for_ai(idx));

        // ズーム中は zoom ハンドラに委ねる (fs_zoom を読む)。KICK も表示保留も false。
        app.fs_zoom = 2.0;
        assert!(!app.should_native_rerender_pdf_for_ai(idx));
        assert!(!app.display_should_defer_final_ai(idx));
        app.fs_zoom = 1.0;

        // デノイズだけでも range 内なら再レンダ要。
        app.settings.global_preset.upscale_model = None;
        app.settings.global_preset.denoise_model =
            Some(ModelKind::DenoiseRealplksr.as_str().to_string());
        assert!(app.should_native_rerender_pdf_for_ai(idx));

        // Codex P2: 高負荷上限 (4096) では cur (100x4000) も range 内だが native (100x200)
        // へ落としてから AI する (PDFium 出力ではなく原寸を AI に流す)。
        app.settings.global_preset.denoise_model = None;
        app.settings.global_preset.upscale_model = Some("auto".to_string());
        app.settings.ai_upscale_size_limit = Some(AiProcessSizeLimit::square(4096));
        assert!(app.should_native_rerender_pdf_for_ai(idx));
        app.settings.ai_upscale_size_limit = Some(AiProcessSizeLimit::square(2048));

        // 収束: native 100x200 の実レンダ着地は 256px clamp 後の 128x256 (raw native では
        // ない、Codex 再々レビュー P2)。ここで再レンダ不要に収束する。
        set_cur(&mut app, 128, 256, &dummy_tex);
        assert!(!app.should_native_rerender_pdf_for_ai(idx));
        assert!(!app.display_should_defer_final_ai(idx));
    }

    #[test]
    fn folder_nav_holdover_bridges_until_new_content_ready() {
        // フォルダナビ (Ctrl+↑↓) で新フォルダ先頭画像のデコード待ち中、holdover
        // (旧フレーム) を維持して黒フレームを挟まないことを固定する。新 idx の
        // 表示物 (full / サムネ) が用意できたら holdover を返さない (stale 防止)。
        // detached window で「次のファイルへ移るたびにちらつく」症状の回帰防止。
        // docs/detached-viewer-lifecycle-redesign-proposal.md 参照。
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let idx = push_image(&mut app, r"C:\pics\a.jpg");
        app.fullscreen_idx = Some(idx);

        let holdover = ctx.load_texture(
            "holdover_old_frame",
            egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE]),
            egui::TextureOptions::LINEAR,
        );
        app.fs_holdover_tex = Some(holdover);
        // capture 時点の generation を lock。その後フォルダ移動で items_generation が進む。
        app.fs_nav_locked_gen = Some(app.items_generation);
        app.items_generation = app.items_generation.wrapping_add(1);

        // 新 idx の full もサムネもまだ無い → holdover で黒を防ぐ。
        assert!(
            app.fs_nav_holdover_tex_for_draw().is_some(),
            "new content not ready yet -> keep showing the previous frame (no black flicker)"
        );

        // 新 idx の full テクスチャが用意できた → holdover は返さない (描画側が new を優先)。
        let new_tex = ctx.load_texture(
            "new_full_frame",
            egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE]),
            egui::TextureOptions::LINEAR,
        );
        app.fs_cache.insert(
            idx,
            FsCacheEntry::Static {
                tex: new_tex,
                pixels: std::sync::Arc::new(egui::ColorImage::new(
                    [1, 1],
                    vec![egui::Color32::WHITE],
                )),
                source_dims: None,
                load_seq: 0,
            },
        );
        assert!(
            app.fs_nav_holdover_tex_for_draw().is_none(),
            "once new content is ready the holdover must stop so no stale image lingers"
        );
    }

