    /// シャープ化以外が既定のページで、強度を上げてから ↩ で 0 に戻すと
    /// 個別設定 (補バッジ / DB 行) が綺麗に消えること。AI 時スキップは固定動作で
    /// 保存フィールドを持たないため、no-op 設定が残る経路が存在しない
    /// (旧チェックボックス実装で問題化した Codex P2 / 2026-06-10 ユーザー要望の回帰ガード)。
    #[test]
    fn resetting_strength_to_zero_removes_override_cleanly() {
        let mut app = setup_app();
        let idx = push_image(&mut app, "C:/pics/reset-clean.jpg");

        let mut active = app.effective_params(idx).clone();
        active.smart_sharpen = 60;
        app.set_page_params(idx, active.clone());
        assert!(
            app.adjustment_page_params.contains_key(&idx),
            "non-zero strength must persist as a page override"
        );

        // ↩ リセット相当: 強度を 0 に戻す → 既定と完全一致して個別設定が消える
        let mut reset = active;
        reset.smart_sharpen = 0;
        app.set_page_params(idx, reset);
        assert!(
            !app.adjustment_page_params.contains_key(&idx),
            "resetting strength to 0 must remove the override (no residual fields)"
        );
    }

    /// AI 失敗確定後、AI 待ちの暫定 final composite (complete=false) が complete に
    /// 昇格すること (Codex P2 2026-06-10)。昇格しないと表示は暫定画像で見えるのに、
    /// complete のみ受け付けるコピー / 書き出し
    /// (`ensure_final_composite_pixels_with_key`) が永久に「最終合成待ち」になる。
    #[test]
    fn ai_failure_promotes_provisional_composite_to_complete() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.settings.ai_feature_mode = crate::settings::AiFeatureMode::HighQuality;
        let idx = push_image(&mut app, "C:/pics/ai-fail.jpg");

        // source 解像度の edit 結果を直接投入
        let edit_image = egui::ColorImage::new([2, 1], vec![egui::Color32::GRAY; 2]);
        let edit_key = dummy_edit_key(&app, idx);
        let edit_tex = ctx.load_texture(
            "ai_fail_edit",
            edit_image.clone(),
            egui::TextureOptions::LINEAR,
        );
        app.edit_result_cache.insert(
            edit_key,
            EditResultEntry {
                pixels: Arc::new(edit_image),
                texture: Some(edit_tex),
            },
        );

        let mut params = crate::adjustment::AdjustParams::default();
        params.upscale_model = Some("realesr_general_v3".to_string());
        app.adjustment_page_params.insert(idx, params.clone());
        let _ = app
            .ensure_final_composite_texture(&ctx, idx)
            .expect("first composite");

        // 「AI ジョブ実行中に作られた暫定 entry + その後 poll で失敗確定」の状態を
        // 決定論的に再現する (テスト環境では AI が起動できず最初から complete に
        // なることがあるため、incomplete を明示的に作る)。
        let ai_key = FinalAiKey {
            edit_key,
            color_ai_hash: hash_adjust_color_ai_params(&params, app.settings.ai_feature_mode),
            bg: 0,
        };
        for (key, entry) in app.final_composite_cache.iter_mut() {
            if key.edit_key.idx == idx {
                entry.complete = false;
            }
        }
        if let Some(pending) = app.final_ai_pending.remove(&ai_key) {
            pending
                .cancel
                .store(true, std::sync::atomic::Ordering::Relaxed);
        }
        app.final_ai_failed.insert(ai_key);

        // 再度 ensure すると failed 分岐で complete=true に昇格し、
        // コピー / 書き出し経路 (complete のみ受け付ける) も復帰する
        let _ = app
            .ensure_final_composite_texture(&ctx, idx)
            .expect("composite after AI failure");
        let complete = app
            .final_composite_cache
            .iter()
            .find(|(key, _)| key.edit_key.idx == idx)
            .map(|(_, entry)| entry.complete)
            .expect("final composite must exist");
        assert!(
            complete,
            "AI failure must promote the provisional composite to complete"
        );
        assert!(
            app.ensure_final_composite_pixels_with_key(&ctx, idx)
                .is_some(),
            "copy/export path must recover after AI failure"
        );
    }

    /// Codex P2 第 2 ラウンド: 最初の ensure 呼び出しの**中**で AI が起動できない
    /// (同フレームで failed 直接 insert / runtime 初期化失敗・モデル不在で何も
    /// 立てずに return) 場合も、stuck な incomplete entry を残さないこと。
    /// 不変条件: incomplete entry が存在してよいのは「AI 結果がまだ届きうる
    /// (pending or cache 済み)」ときだけ。
    #[test]
    fn ensure_final_composite_never_leaves_stuck_incomplete_entry() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.settings.ai_feature_mode = crate::settings::AiFeatureMode::HighQuality;
        let idx = push_image(&mut app, "C:/pics/ai-no-start.jpg");

        let edit_image = egui::ColorImage::new([2, 1], vec![egui::Color32::GRAY; 2]);
        let edit_key = dummy_edit_key(&app, idx);
        let edit_tex = ctx.load_texture(
            "ai_no_start_edit",
            edit_image.clone(),
            egui::TextureOptions::LINEAR,
        );
        app.edit_result_cache.insert(
            edit_key,
            EditResultEntry {
                pixels: Arc::new(edit_image),
                texture: Some(edit_tex),
            },
        );

        let mut params = crate::adjustment::AdjustParams::default();
        params.upscale_model = Some("realesr_general_v3".to_string());
        app.adjustment_page_params.insert(idx, params.clone());
        let _ = app
            .ensure_final_composite_texture(&ctx, idx)
            .expect("composite");

        let ai_key = FinalAiKey {
            edit_key,
            color_ai_hash: hash_adjust_color_ai_params(&params, app.settings.ai_feature_mode),
            bg: 0,
        };
        let complete = app
            .final_composite_cache
            .iter()
            .find(|(key, _)| key.edit_key.idx == idx)
            .map(|(_, entry)| entry.complete)
            .expect("final composite must exist");
        let ai_may_still_arrive =
            app.final_ai_pending.contains_key(&ai_key) || app.final_ai_cache.contains_key(&ai_key);
        assert!(
            complete || ai_may_still_arrive,
            "an incomplete composite may exist only while an AI result can still arrive \
             (failed={})",
            app.final_ai_failed.contains(&ai_key)
        );
    }

    /// final 専用項目 (シャープ化 / post_filter) だけの変更は
    /// `clear_final_stage_only_caches` 経由で final AI cache を保持する
    /// (Codex P1: `clear_adjustment_caches` に流すと強度スライダーや T キー循環の
    /// たびに final AI が cancel → 再実行されてしまう)。
    #[test]
    fn final_stage_only_clear_keeps_final_ai_cache() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let idx = push_image(&mut app, "C:/pics/sharpen.jpg");
        let (edit_key, final_key) = insert_edit_and_final_cache(&mut app, &ctx, idx, "sharpen");

        app.clear_final_stage_only_caches(idx);

        assert!(
            app.final_ai_cache
                .keys()
                .any(|key| key.edit_key == edit_key),
            "sharpen-only clear must keep final_ai_cache (AI input unchanged)"
        );
        assert!(
            !app.final_composite_cache.contains_key(&final_key),
            "sharpen-only clear must drop the final composite"
        );
        assert!(
            app.edit_result_cache.contains_key(&edit_key),
            "sharpen-only clear must keep the edit result"
        );

        // 対照: 通常の色調系 clear は final AI cache も落とす (AI 入力が変わるため)。
        let (edit_key2, _) = insert_edit_and_final_cache(&mut app, &ctx, idx, "sharpen2");
        app.clear_adjustment_caches(idx);
        assert!(
            !app.final_ai_cache
                .keys()
                .any(|key| key.edit_key == edit_key2),
            "color-path clear must still drop final_ai_cache"
        );
    }

