    /// 最終表示段スマートシャープ: 強度変更で final composite key は切り替わるが、
    /// final AI key (color_ai hash) は不変 — AI 再実行なしで再合成だけが走る。
    #[test]
    fn smart_sharpen_changes_final_hash_but_not_color_ai_hash() {
        let mode = crate::settings::AiFeatureMode::HighQuality;
        let base = crate::adjustment::AdjustParams::default();
        let sharpened = crate::adjustment::AdjustParams {
            smart_sharpen: 60,
            ..Default::default()
        };

        assert_ne!(
            hash_adjust_final_params(&base, mode, false),
            hash_adjust_final_params(&sharpened, mode, false),
            "smart_sharpen must invalidate the final composite cache"
        );
        assert_eq!(
            hash_adjust_color_ai_params(&base, mode),
            hash_adjust_color_ai_params(&sharpened, mode),
            "smart_sharpen must NOT invalidate the final AI cache"
        );
        // 強度違い同士も別 key になる。
        let stronger = crate::adjustment::AdjustParams {
            smart_sharpen: 100,
            ..Default::default()
        };
        assert_ne!(
            hash_adjust_final_params(&sharpened, mode, false),
            hash_adjust_final_params(&stronger, mode, false),
        );
        // post_filter バイパス中 (消しゴム / 隠蔽 / 分析) もシャープ化は hash に乗る
        // (= バイパス中も適用されたまま)。
        assert_ne!(
            hash_adjust_final_params(&base, mode, true),
            hash_adjust_final_params(&sharpened, mode, true),
        );
    }

    /// 「AI アップスケール実行時は適用しない」(既定 ON): 合成ベースが
    /// `used_upscale=true` の AI 結果なら、出力サイズが入力と同じでもシャープ化を外す。
    #[test]
    fn smart_sharpen_skips_when_composite_uses_upscaled_ai_result() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.settings.ai_feature_mode = crate::settings::AiFeatureMode::HighQuality;
        let idx = push_image(&mut app, "C:/pics/skip-after-ai.jpg");

        // source 解像度の edit 結果 (4x1 の強エッジ)
        let edge_row = |w: usize, h: usize| {
            let mut px = Vec::with_capacity(w * h);
            for _ in 0..h {
                for x in 0..w {
                    let v = if x < w / 2 { 40 } else { 200 };
                    px.push(egui::Color32::from_rgb(v, v, v));
                }
            }
            egui::ColorImage::new([w, h], px)
        };
        let edit_image = edge_row(4, 1);
        let edit_key = dummy_edit_key(&app, idx);
        let edit_tex = ctx.load_texture(
            "skip_ai_edit",
            edit_image.clone(),
            egui::TextureOptions::LINEAR,
        );
        app.edit_result_cache.insert(
            edit_key,
            EditResultEntry {
                pixels: Arc::new(edit_image),
                texture: Some(edit_tex),
            },
        );

        // ページ個別: シャープ 100 + アップスケール指定
        let mut params = crate::adjustment::AdjustParams::default();
        params.smart_sharpen = 100;
        params.upscale_model = Some("realesr_general_v3".to_string());
        app.adjustment_page_params.insert(idx, params.clone());

        // render-to-target で入力と同サイズへ着地した upscaler 結果を直接投入
        let ai_image = edge_row(4, 1);
        let ai_key = FinalAiKey {
            edit_key,
            color_ai_hash: hash_adjust_color_ai_params(&params, app.settings.ai_feature_mode),
            bg: 0,
        };
        app.final_ai_cache.insert(
            ai_key,
            FinalAiEntry {
                pixels: Arc::new(ai_image.clone()),
                used_upscale: true,
            },
        );

        let composite_pixels = |app: &App| {
            app.final_composite_cache
                .iter()
                .find(|(key, _)| key.edit_key.idx == idx)
                .map(|(_, entry)| Arc::clone(&entry.pixels))
                .expect("final composite must exist")
        };

        // upscaler 経由の結果には固定でシャープを掛けない
        let _ = app
            .ensure_final_composite_texture(&ctx, idx)
            .expect("composite with upscaled AI result");
        let skipped = composite_pixels(&app);
        assert_eq!(skipped.size, [4, 1], "AI 結果のサイズで合成される");
        assert_eq!(
            skipped.pixels, ai_image.pixels,
            "同サイズへ着地した AI アップスケール出力にもシャープを掛けない (固定動作)"
        );

        // 対照: サイズ不変の AI 結果 (デノイズのみ相当) には通常どおりシャープが掛かる
        let mut params_dn = crate::adjustment::AdjustParams::default();
        params_dn.smart_sharpen = 100;
        params_dn.denoise_model = Some(crate::ai::ModelKind::DenoiseRealplksr.as_str().to_string());
        app.adjustment_page_params.insert(idx, params_dn.clone());
        let dn_image = edge_row(4, 1);
        let dn_key = FinalAiKey {
            edit_key,
            color_ai_hash: hash_adjust_color_ai_params(&params_dn, app.settings.ai_feature_mode),
            bg: 0,
        };
        app.final_ai_cache.insert(
            dn_key,
            FinalAiEntry {
                pixels: Arc::new(dn_image.clone()),
                used_upscale: false,
            },
        );
        app.final_composite_cache.clear();
        let _ = app
            .ensure_final_composite_texture(&ctx, idx)
            .expect("composite with denoise-only AI result");
        let sharpened = composite_pixels(&app);
        assert_eq!(sharpened.size, [4, 1]);
        assert_ne!(
            sharpened.pixels, dn_image.pixels,
            "サイズ不変の AI 結果 (デノイズのみ) には通常どおりシャープが掛かる"
        );
    }

