    fn insert_static_fs_entry(app: &mut App, ctx: &egui::Context, idx: usize, label: &str) {
        let pixels = egui::ColorImage::new([2, 1], vec![egui::Color32::WHITE; 2]);
        let tex = ctx.load_texture(label, pixels.clone(), egui::TextureOptions::LINEAR);
        app.fs_cache.insert(
            idx,
            FsCacheEntry::Static {
                tex,
                pixels: std::sync::Arc::new(pixels),
                source_dims: Some([2, 1]),
                load_seq: 0,
            },
        );
    }

    fn assert_rect_close(actual: egui::Rect, expected: egui::Rect) {
        let eps = 0.001;
        assert!(
            (actual.min.x - expected.min.x).abs() < eps
                && (actual.min.y - expected.min.y).abs() < eps
                && (actual.max.x - expected.max.x).abs() < eps
                && (actual.max.y - expected.max.y).abs() < eps,
            "actual={actual:?} expected={expected:?}"
        );
    }

    fn assert_frozen_background_white(background: &DetachedImageWindowFrozenBackground) {
        match background {
            DetachedImageWindowFrozenBackground::Solid(color) => {
                assert_eq!(*color, egui::Color32::WHITE)
            }
            _ => panic!("expected frozen page to preserve white transparent background"),
        }
    }

    fn test_zip_nav_for(zip_path: PathBuf, names: &[&str]) -> crate::zip_tree::ZipNavState {
        let entries: Vec<crate::zip_loader::ZipImageEntry> = names
            .iter()
            .map(|n| crate::zip_loader::ZipImageEntry {
                entry_name: n.to_string(),
                uncompressed_size: 0,
                mtime: 0,
            })
            .collect();
        let tree = std::sync::Arc::new(crate::zip_tree::ZipTree::build(zip_path, entries));
        crate::zip_tree::ZipNavState::new(tree)
    }

