    #[test]
    #[cfg(windows)]
    fn detached_host_lost_before_render_drops_stale_hwnd_without_recreate() {
        // host_lost を検出しても viewport を recreate しない (= generation を bump
        // しない) ことを固定する。recreate するとナビのたびに既定サイズの窓が一瞬
        // 出るフラッシュ + recreate ループになる。
        // docs/detached-viewer-lifecycle-redesign-proposal.md BA-1/BA-2/BA-3。
        let mut app = setup_app();
        app.fullscreen_idx = Some(push_image(&mut app, r"C:\pics\a.jpg"));
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.fs_viewport_shown = true;
        app.fs_viewport_presentation = Some(ViewerPresentation::DetachedWindow);
        app.detached_viewer_window_id = Some(12);
        app.fs_viewport_generation = 7;
        // 解放済み等で IsWindow=false になる stale hwnd を模す。
        set_detached_host_for_test(&mut app, 12, 0x1234, false);

        let viewport_id_before = app.fullscreen_viewport_id();
        app.handle_detached_viewer_host_lost_before_render();

        assert_eq!(
            app.detached_window_hwnd_raw_for_window_id(12),
            0,
            "stale hwnd must be dropped so the next frame can recapture the live window"
        );
        assert_eq!(
            app.fs_viewport_generation, 7,
            "host_lost must not bump the viewport generation (no recreate)"
        );
        assert!(
            app.fs_viewport_shown,
            "viewport stays shown; capture re-grabs the live window without recreate"
        );
        assert_eq!(
            app.fullscreen_viewport_id(),
            viewport_id_before,
            "viewport id stays stable (no recreate)"
        );
    }

    #[test]
    #[cfg(windows)]
    fn detached_inactive_builder_seeds_placement_unless_host_is_alive() {
        // holdover / cleanup 用 inactive builder は、host HWND が **生存していない**
        // (= 窓が未生成 or 死んでいて egui が再生成する) ときだけ placement を seed して
        // 既定サイズ 822x656 のフラッシュを防ぐ。host が生存しているときは geometry を触らず、
        // enumerate 待ち中の drag/resize 引き戻しを防ぐ (Codex P2)。
        // 判定は `== 0` ではなく `alive()` にする: stale (死んだ) HWND をまだ指している (!=0)
        // 間に egui が窓を再生成すると、`== 0` では seed を取りこぼして既定サイズ窓が生えてしまう
        // (2026-07-01 ハンドオフの疑い経路)。
        let mut app = setup_app();
        let idx = push_image(&mut app, r"C:\pics\a.jpg");
        app.fullscreen_idx = Some(idx);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.fs_viewport_presentation = Some(ViewerPresentation::DetachedWindow);

        // host 未捕捉 (== 0) = 新規生成相当 → 保存済みサイズで生成 (既定 822x656 で出さない)。
        app.detached_viewer_window_id = Some(12);
        app.detached_window_hwnd_clear(12);
        let builder = app.build_inactive_fullscreen_viewport_builder(idx);
        assert!(
            builder.inner_size.is_some(),
            "fresh detached window must be created at the saved size, not the egui default"
        );

        // host が stale (死んだ HWND を !=0 で指している) = egui が窓を再生成する →
        // 再生成された窓が既定サイズで一瞬出ないよう、seed し続ける (旧 `== 0` の取りこぼし修正)。
        set_detached_host_for_test(&mut app, 12, 0x1234, false);
        let builder = app.build_inactive_fullscreen_viewport_builder(idx);
        assert!(
            builder.inner_size.is_some(),
            "a stale (dead) host HWND still means egui will recreate the OS window; it must be \
             seeded at the saved size to avoid the default-size flash"
        );

        // host が生存している既存 window → geometry を触らない (Codex P2)。
        set_detached_host_for_test(&mut app, 12, 0x5678, true);
        let builder = app.build_inactive_fullscreen_viewport_builder(idx);
        assert_eq!(
            builder.inner_size, None,
            "existing (alive) detached window must not be force-resized while waiting on enumerate (Codex P2)"
        );
        assert_eq!(
            builder.position, None,
            "existing (alive) detached window must not be repositioned while waiting on enumerate (Codex P2)"
        );
    }

    #[test]
    #[cfg(windows)]
    fn detached_viewer_should_seed_placement_tracks_host_liveness() {
        // active / inactive / keep-alive backstop の 3 経路が共有する述語。host HWND が
        // 生存していない (未捕捉 or stale) 間だけ placement を seed して既定サイズ 822x656 の
        // フラッシュを防ぐ。生存している間は seed しない (Codex P2)。backstop 経路はこの述語で
        // 覆われる (Codex P2 の `== 0` 取りこぼし修正)。
        let mut app = setup_app();

        // 未捕捉 (== 0) → seed。
        app.detached_viewer_window_id = Some(12);
        app.detached_window_hwnd_clear(12);
        assert!(app.detached_viewer_should_seed_placement());

        // stale (死んだ HWND を !=0 で指したまま egui 再生成) → seed し続ける。
        set_detached_host_for_test(&mut app, 12, 0x1234, false);
        assert!(
            app.detached_viewer_should_seed_placement(),
            "a nonzero-but-dead host HWND must still seed so egui recreation uses the saved size"
        );

        // 生存している既存窓 → seed しない。
        set_detached_host_for_test(&mut app, 12, 0x5678, true);
        assert!(
            !app.detached_viewer_should_seed_placement(),
            "an alive captured host must not be force-resized (Codex P2)"
        );
    }

    #[test]
    #[cfg(windows)]
    fn folder_nav_close_preserves_detached_window_id_for_reuse() {
        // フォルダナビ (Ctrl+↑↓) の reopen では、load_folder → start_loading_items が
        // new items 導入前に close_fullscreen を呼ぶ。fs_nav ロック中はその close で
        // detached_viewer_window_id を消さず維持し、reopen 側が新しい window_id を
        // allocate して別ウィンドウ (fullscreen_viewport_id 変化 → OS 窓再生成) を
        // 作らないことを固定する。実機動画 (2026-06-28) で「次フォルダへ移るたびに
        // ウィンドウ再表示 + 既定サイズ小窓が一瞬」を確認した回帰の防止。
        let mut app = setup_app();
        let idx = push_image(&mut app, r"C:\pics\a.jpg");
        app.fullscreen_idx = Some(idx);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.detached_viewer_window_id = Some(42);
        app.detached_viewer_folder_nav_reuse_window_once = true;
        app.settings.detached_viewer_open_images_in_window = true;
        app.fs_nav_locked_gen = Some(app.items_generation);
        // session が alive (= 未 close) の間は detached identity を維持する (新ガード)。
        app.begin_active_detached_session(42, crate::app::DetachedSource::Image);

        // ロック中は「現在の detached ウィンドウを park する」判定を抑止 (= 別ウィンドウ
        // 化せず内容差し替えで再利用)。
        assert!(
            !app.should_preserve_active_detached_image_window_for_main_context_change(),
            "folder-nav must not park the active detached window; it is reused in place"
        );

        app.prepare_viewer_presentation_close();
        assert_eq!(
            app.detached_viewer_window_id,
            Some(42),
            "folder-nav reopen must keep the detached window_id so the same OS window is reused"
        );
        assert!(
            app.detached_viewer_folder_nav_reuse_window_once,
            "folder-nav reuse intent must survive the intermediate close"
        );

        // 真の close 相当: 明示終了経路が session を畳んでから close_fullscreen を通る。
        // session が None になったら通常どおり detached identity をクリアする。
        app.begin_active_detached_session_close("test");
        app.finish_active_detached_session_close("test");
        app.fs_nav_locked_gen = None;
        app.detached_viewer_folder_nav_reuse_window_once = false;
        app.prepare_viewer_presentation_close();
        assert_eq!(
            app.detached_viewer_window_id, None,
            "a normal (non-folder-nav) close still tears down the detached identity"
        );
    }

    #[test]
    #[cfg(windows)]
    fn folder_nav_close_preserves_borderless_fullscreen_while_session_alive() {
        // F11 仮想フルスクリーン (borderless) が folder-nav の中間 close (close_fullscreen →
        // prepare_viewer_presentation_close) で失われない = 最大化ウィンドウに化けないことを固定。
        // 判定は fullscreen_idx ではなく session 状態なので、close で fullscreen_idx=None に
        // なっていても維持できる (旧 viewer_session_is_detached 依存だと誤クリアしていた)。
        let mut app = setup_app();
        let idx = push_image(&mut app, r"C:\pics\a.jpg");
        app.fullscreen_idx = Some(idx);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.detached_viewer_window_id = Some(7);
        app.detached_viewer_borderless_fullscreen = true;
        app.begin_active_detached_session(7, crate::app::DetachedSource::Image);

        // close_fullscreen が先に fullscreen_idx=None にしてから prepare を呼ぶ状況を再現。
        app.fullscreen_idx = None;
        app.prepare_viewer_presentation_close();
        assert!(
            app.detached_viewer_borderless_fullscreen,
            "F11 borderless must survive the intermediate folder-nav close (no revert to maximized)"
        );

        // 真の close (session を畳んでから) では borderless もクリアする。
        app.begin_active_detached_session_close("test");
        app.finish_active_detached_session_close("test");
        app.prepare_viewer_presentation_close();
        assert!(
            !app.detached_viewer_borderless_fullscreen,
            "a genuine close (session ended) clears borderless state"
        );
    }

    #[test]
    #[cfg(windows)]
    fn folder_nav_reopen_reuses_active_detached_window_id() {
        // detached ウィンドウのフォルダナビ reopen は、(PDF/ZIP の非同期 enumerate などで)
        // window_id が一旦 None になっても直前の window_id を再利用し、fullscreen_viewport_id
        // (= detached では window_id 由来) を安定させる。これで次フォルダへ移るたびに
        // ViewportId が変わって OS ウィンドウが破棄→再生成される (= 小窓カスケード /
        // DWM フェード) のを防ぐ。v2.2.0 は generation 由来で安定していた挙動の復元。
        let mut app = setup_app();
        let idx = push_image(&mut app, r"C:\pics\a.jpg");
        app.fullscreen_idx = Some(idx);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;

        // 初回 (grid から): 新規 allocate。
        app.fs_open_intent_from_grid = true;
        let first = app.ensure_detached_viewer_window_id();
        let vid_first = app.fullscreen_viewport_id();
        assert_eq!(app.last_active_detached_window_id, Some(first));

        // フォルダナビの close 相当で window_id が None になる。
        app.detached_viewer_window_id = None;

        // folder-nav reopen (grid 由来でない) は同じ window_id を再利用 → ViewportId 不変。
        app.fs_open_intent_from_grid = false;
        let reopened = app.ensure_detached_viewer_window_id();
        assert_eq!(
            reopened, first,
            "folder-nav reopen must reuse the previous detached window_id"
        );
        assert_eq!(
            app.fullscreen_viewport_id(),
            vid_first,
            "viewport id must stay stable across folder-nav so the OS window is not recreated"
        );

        // grid からの新規オープンは別ウィンドウを作る (= 新しい id を allocate)。
        app.detached_viewer_window_id = None;
        app.fs_open_intent_from_grid = true;
        let fresh = app.ensure_detached_viewer_window_id();
        assert_ne!(
            fresh, first,
            "an explicit grid-originated open allocates a new window id"
        );
    }

    #[test]
    #[cfg(windows)]
    fn keepalive_session_state_truth_table() {
        // keep-alive の単一真実 (docs/detached-viewer-keepalive-design.md §3.1) の挙動を固定。
        let mut app = setup_app();
        // 初期: セッションなし → 生かさない。
        assert!(!app.detached_active_window_alive_wanted());
        assert_eq!(app.active_detached_session_viewport_id(), None);

        // begin → 生かす。viewport id は window_id 由来で安定。
        app.begin_active_detached_session(7, crate::app::DetachedSource::Image);
        assert!(app.detached_active_window_alive_wanted());
        assert_eq!(
            app.active_detached_session_viewport_id(),
            Some(App::detached_image_window_viewport_id(7))
        );

        // folder-nav reopen 相当 (同じ window_id で re-begin) → 据え置きで生かす。
        app.begin_active_detached_session(7, crate::app::DetachedSource::Book);
        assert!(app.detached_active_window_alive_wanted());
        assert_eq!(
            app.active_detached_session_viewport_id(),
            Some(App::detached_image_window_viewport_id(7))
        );

        // closing=true → teardown 中は生かさない (backstop も止まる)。
        app.begin_active_detached_session_close("test");
        assert!(!app.detached_active_window_alive_wanted());

        // finish → None。
        app.finish_active_detached_session_close("test");
        assert!(!app.detached_active_window_alive_wanted());
        assert_eq!(app.active_detached_session_viewport_id(), None);
    }

    #[test]
    #[cfg(windows)]
    fn detached_window_runtime_reducer_representative_sequence() {
        // R2b Part 1: active session の closing bool を廃止し、runtime.state を
        // reducer の正にした代表列を固定する。
        let mut app = setup_app();
        let window_id = 31;

        app.transition_detached_window_state(
            window_id,
            DetachedWindowState::Opening,
            "test_opening",
        );
        assert_eq!(
            app.detached_window_state(window_id),
            Some(DetachedWindowState::Opening)
        );

        app.begin_active_detached_session(window_id, DetachedSource::Image);
        assert!(app.detached_active_window_alive_wanted());
        assert_eq!(
            app.detached_window_state(window_id),
            Some(DetachedWindowState::Active)
        );

        app.transition_detached_window_state(window_id, DetachedWindowState::Parked, "test_parked");
        assert_eq!(
            app.detached_window_state(window_id),
            Some(DetachedWindowState::Parked)
        );

        app.transition_detached_window_state(
            window_id,
            DetachedWindowState::Resuming,
            "test_resuming",
        );
        assert_eq!(
            app.detached_window_state(window_id),
            Some(DetachedWindowState::Resuming)
        );

        app.begin_active_detached_session(window_id, DetachedSource::Image);
        assert_eq!(
            app.detached_window_state(window_id),
            Some(DetachedWindowState::Active)
        );

        app.begin_active_detached_session_close("test_closing");
        assert!(!app.detached_active_window_alive_wanted());
        assert_eq!(
            app.detached_window_state(window_id),
            Some(DetachedWindowState::Closing)
        );
        app.finish_active_detached_session_close("test_finish");
        let removed = app.remove_detached_window_runtime(window_id, "test_removed");
        assert!(removed.is_some());
        assert_eq!(app.detached_window_state(window_id), None);
    }

    #[test]
    #[cfg(windows)]
    fn detached_runtime_placement_seeds_from_settings_then_overrides_with_runtime() {
        let mut app = setup_app();
        let seed = crate::settings::DetachedViewerWindowPlacement {
            x: 100.0,
            y: 120.0,
            w: 960.0,
            h: 720.0,
            maximized: false,
        };
        let runtime = crate::settings::DetachedViewerWindowPlacement {
            x: 320.0,
            y: 220.0,
            w: 1180.0,
            h: 760.0,
            maximized: false,
        };
        app.settings.detached_viewer_window_placement = Some(seed);

        app.begin_active_detached_session(41, DetachedSource::Image);
        assert_eq!(app.detached_window_runtime_placement(41), Some(seed));
        assert_eq!(app.active_detached_viewer_current_placement(), seed);

        app.set_detached_window_runtime_placement(41, runtime, "test_runtime_override");
        assert_eq!(app.active_detached_viewer_current_placement(), runtime);
        assert_eq!(
            app.settings.detached_viewer_window_placement,
            Some(seed),
            "live placement updates must not rewrite settings before close"
        );
    }

    #[test]
    #[cfg(windows)]
    fn detached_builder_placement_latch_does_not_follow_live_drag_updates() {
        let mut app = setup_app();
        let initial = crate::settings::DetachedViewerWindowPlacement {
            x: 1564.0,
            y: 240.66667,
            w: 1167.0,
            h: 765.0,
            maximized: false,
        };
        let alternate = crate::settings::DetachedViewerWindowPlacement {
            x: 1578.6666,
            y: 244.0,
            w: 1167.0,
            h: 765.0,
            maximized: false,
        };

        app.begin_active_detached_session(44, DetachedSource::Video);
        app.set_detached_window_runtime_placement(44, initial, "test_initial");

        assert_eq!(
            app.active_detached_builder_placement_latch(true, "test_need_show"),
            initial,
            "need_show/host-seed frames capture the current live placement into the builder latch"
        );

        for i in 0..8 {
            let live = if i % 2 == 0 { alternate } else { initial };
            app.set_detached_window_runtime_placement(44, live, "test_drag_report");
            assert_eq!(
                app.active_detached_viewer_current_placement(),
                live,
                "live runtime placement should continue to track the OS-reported drag position"
            );
            assert_eq!(
                app.active_detached_builder_placement_latch(false, "test_video_per_frame_seed"),
                initial,
                "video's per-frame seed must reuse the latched builder placement instead of echoing live A/B reports"
            );
        }
    }

    #[test]
