    #[test]
    #[cfg(windows)]
    fn deferred_activation_queues_until_next_root_frame() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        app.frame_counter = 40;
        app.settings.detached_viewer_open_images_in_window = false;
        app.items = vec![GridItem::PdfPage {
            pdf_path: PathBuf::from(r"C:\books\a.pdf"),
            page_num: 7,
            content_type: None,
        }];
        app.thumbnails = vec![ThumbnailState::Pending];
        app.image_metas = vec![None];
        app.visible_indices = vec![0];
        app.current_folder = Some(PathBuf::from(r"C:\books\a.pdf"));
        app.selected = Some(0);
        let stamp = app
            .viewer_sync_stamp_for_idx(0)
            .expect("PDF page should produce a sync stamp");

        let texture = ctx.load_texture(
            "deferred-activation",
            egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE]),
            egui::TextureOptions::LINEAR,
        );
        let placement = app.detached_viewer_window_placement();
        let snapshot = DetachedImageWindowSnapshot {
            id: 7,
            texture,
            title: "a.jpg - mimageviewer".to_string(),
            location_display: "a.jpg".to_string(),
            image_dims: Some((1, 1)),
            rotation: crate::rotation_db::Rotation::None,
            zoom_pan: None,
            free_rotation: 0.0,
            image_rect_norm: egui::Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)),
            image_content_bbox: None,
            frozen_continuous_pages: Vec::new(),
            reopen_descriptor: None,
            reopen_sync_stamp: Some(stamp),
            activation_ready_frame: 0,
            activation_armed: true,
            focused_last_frame: false,
            initial_placement_applied: true,
            paused_bundle: None,
        };
        app.detached_image_windows.push(snapshot);
        app.transition_detached_window_state(7, DetachedWindowState::Parked, "test_deferred");
        app.set_detached_window_runtime_placement(7, placement, "test_deferred_activation");

        let view = DeferredDetachedImageWindowView::from_snapshot(
            &app.detached_image_windows[0],
            placement,
            false,
        );
        let shared = app.deferred_detached_image_window_shared(view);
        shared.push_event(DeferredDetachedImageWindowEvent::Frame {
            id: 7,
            viewport_close_requested: false,
            bar_close_requested: false,
            focused: true,
            placement_update: None,
            pixels_per_point: 1.5,
            apply_initial_placement: false,
        });

        app.process_deferred_detached_image_window_events_for_test(&ctx);
        app.queue_deferred_detached_window_activation(7, "test_watcher");

        assert_eq!(
            app.detached_image_windows.len(),
            1,
            "the queued frame must keep the deferred snapshot registered"
        );
        assert!(
            app.detached_window_deferred_activation_pending(7),
            "deferred callback activation should only queue during the callback/root handoff frame"
        );
        assert!(
            app.active_detached_viewer_context.is_none(),
            "activation must not commit after active immediate rendering already ran in this root frame"
        );

        app.frame_counter += 1;
        assert!(app.commit_pending_deferred_detached_window_activation(&ctx));

        assert!(app.detached_image_windows.is_empty());
        assert!(
            !app.detached_window_deferred_activation_pending(7),
            "commit consumes the queued activation"
        );
        assert_eq!(app.active_detached_session.unwrap().window_id, 7);
        assert_eq!(app.fullscreen_idx, Some(0));
        assert_eq!(app.detached_viewer_window_id, Some(7));
        assert_eq!(app.viewer_presentation, ViewerPresentation::DetachedWindow);
    }

    #[test]
    #[cfg(windows)]
    fn deferred_placement_event_rejects_default_geometry_on_app_side() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let texture = ctx.load_texture(
            "deferred-placement",
            egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE]),
            egui::TextureOptions::LINEAR,
        );
        let previous = crate::settings::DetachedViewerWindowPlacement {
            x: 502.0,
            y: 138.0,
            w: 1278.0,
            h: 840.0,
            maximized: false,
        };
        let default_candidate = crate::settings::DetachedViewerWindowPlacement {
            x: 152.0,
            y: 152.0,
            w: 533.3333,
            h: 400.0,
            maximized: false,
        };
        let snapshot = DetachedImageWindowSnapshot {
            id: 7,
            texture,
            title: "deferred.jpg - mimageviewer".to_string(),
            location_display: "deferred.jpg".to_string(),
            image_dims: Some((1, 1)),
            rotation: crate::rotation_db::Rotation::None,
            zoom_pan: None,
            free_rotation: 0.0,
            image_rect_norm: egui::Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)),
            image_content_bbox: None,
            frozen_continuous_pages: Vec::new(),
            reopen_descriptor: None,
            reopen_sync_stamp: None,
            activation_ready_frame: 0,
            activation_armed: true,
            focused_last_frame: false,
            initial_placement_applied: true,
            paused_bundle: None,
        };
        app.detached_image_windows.push(snapshot);
        app.transition_detached_window_state(7, DetachedWindowState::Parked, "test_deferred");
        app.set_detached_window_runtime_placement(7, previous, "test_deferred_previous");
        let view = DeferredDetachedImageWindowView::from_snapshot(
            &app.detached_image_windows[0],
            previous,
            false,
        );
        let shared = app.deferred_detached_image_window_shared(view);
        shared.push_event(DeferredDetachedImageWindowEvent::Frame {
            id: 7,
            viewport_close_requested: false,
            bar_close_requested: false,
            focused: false,
            placement_update: Some(default_candidate),
            pixels_per_point: 1.5,
            apply_initial_placement: false,
        });

        app.process_deferred_detached_image_window_events_for_test(&ctx);

        assert_eq!(
            app.detached_window_runtime_placement(7),
            Some(previous),
            "deferred PlacementObserved must pass through the same default-geometry rejection as immediate passive windows"
        );
        assert!(
            !app.detached_image_windows[0].initial_placement_applied,
            "rejecting a default geometry observation asks the next deferred registration to re-seed placement"
        );
    }

    #[test]
    fn detached_viewer_maximized_save_preserves_restore_placement() {
        let mut app = setup_app();
        let seed = crate::settings::DetachedViewerWindowPlacement {
            x: 120.0,
            y: 140.0,
            w: 860.0,
            h: 640.0,
            maximized: false,
        };
        app.settings.detached_viewer_window_placement = Some(seed);
        app.detached_viewer_window_id = Some(12);
        app.begin_active_detached_session(12, DetachedSource::Image);
        app.set_detached_window_runtime_placement(12, seed, "test_maximized");

        let outer = egui::Rect::from_min_size(egui::pos2(0.0, 0.0), egui::vec2(2560.0, 1440.0));
        let restore = app.save_detached_viewer_placement_from_logical_rect(outer, None, 1.5, true);
        assert!(restore.is_none());

        let placement = app
            .detached_window_runtime_placement(12)
            .expect("maximized placement should be saved in runtime");
        assert_eq!(placement.x, 120.0);
        assert_eq!(placement.y, 140.0);
        assert_eq!(placement.w, 860.0);
        assert_eq!(placement.h, 640.0);
        assert!(placement.maximized);
        assert_eq!(app.settings.detached_viewer_window_placement, Some(seed));
    }

