        app.zip_nav_show_current_level();
        let idx = app
            .items
            .iter()
            .position(
                |it| matches!(it, GridItem::ZipImage { entry_name, .. } if entry_name == "p1.jpg"),
            )
            .expect("root page should be materialized");
